/// Public lookup facade used by both the library API and CLI.
#[derive(Debug)]
pub struct Library {
    snapshot: IndexSnapshot,
    store: SegmentStore,
}

impl Library {
    /// Open the directory containing the immutable index and segment files.
    pub fn open(index_path: impl Into<PathBuf>) -> Result<Self> {
        let index_path = index_path.into();
        let root = index_path
            .parent()
            .unwrap_or_else(|| Path::new("."))
            .to_path_buf();
        let snapshot = IndexSnapshot::new(root, "a", "z", "segment-0001.tsv");
        Ok(Self {
            snapshot,
            store: SegmentStore::default(),
        })
    }

    /// Find one record by key through the index, store, and cache layers.
    pub fn find_record(&self, query: &LookupQuery) -> Result<Option<LedgerRecord>> {
        let outcome = self.snapshot.lookup(&self.store, query)?;
        Ok(outcome.record)
    }

    /// Return an explicit validation error for a query that cannot be parsed.
    pub fn find_raw(&self, key: impl Into<String>) -> Result<Option<LedgerRecord>> {
        let query = LookupQuery::new(key)?;
        self.find_record(&query)
    }
}
use crate::error::Result;
use crate::query::LookupQuery;
use crate::record::LookupOutcome;
use crate::store::SegmentStore;
use std::path::{Path, PathBuf};

/// Immutable mapping from a key range to one segment file.
#[derive(Debug, Clone)]
pub(crate) struct IndexSnapshot {
    root: PathBuf,
    first_key: String,
    last_key: String,
    segment_name: String,
}

impl IndexSnapshot {
    pub(crate) fn new(
        root: PathBuf,
        first_key: impl Into<String>,
        last_key: impl Into<String>,
        segment_name: impl Into<String>,
    ) -> Self {
        Self {
            root,
            first_key: first_key.into(),
            last_key: last_key.into(),
            segment_name: segment_name.into(),
        }
    }

    /// Resolve a query to the segment and use the store to read its records.
    pub(crate) fn lookup(
        &self,
        store: &SegmentStore,
        query: &LookupQuery,
    ) -> Result<LookupOutcome> {
        let segment_path = self.segment_path();
        let records = store.read_segment(&segment_path)?;
        let record = if query.key() < self.first_key.as_str()
            || query.key() > self.last_key.as_str()
        {
            None
        } else {
            records.iter().find(|record| record.key == query.key()).cloned()
        };
        Ok(LookupOutcome {
            segment_name: self.segment_name.clone(),
            record,
        })
    }

    fn segment_path(&self) -> PathBuf {
        self.root.join(&self.segment_name)
    }

    #[allow(dead_code)]
    fn index_path(root: &Path) -> PathBuf {
        root.join("index.meta")
    }
}
use crate::cache::IndexCache;
use crate::error::{LookupError, Result};
use crate::record::LedgerRecord;
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::Arc;

/// Reads tab-delimited segment files through the shared immutable cache.
#[derive(Debug, Default)]
pub(crate) struct SegmentStore {
    cache: IndexCache,
}

impl SegmentStore {
    /// Decode a segment, reusing the cached representation when available.
    pub(crate) fn read_segment(&self, path: &Path) -> Result<Arc<Vec<LedgerRecord>>> {
        let owned_path: PathBuf = path.to_path_buf();
        self.cache.get_or_load(owned_path.clone(), || {
            let bytes = fs::read(&owned_path)
                .map_err(|_| LookupError::MissingSegment(owned_path.display().to_string()))?;
            decode_segment(&owned_path, &bytes)
        })
    }
}

fn decode_segment(path: &Path, bytes: &[u8]) -> Result<Vec<LedgerRecord>> {
    let text = std::str::from_utf8(bytes)
        .map_err(|_| LookupError::CorruptSegment(path.display().to_string()))?;
    text.lines()
        .map(|line| {
            let (key, value) = line
                .split_once('\t')
                .ok_or_else(|| LookupError::CorruptSegment(path.display().to_string()))?;
            Ok(LedgerRecord {
                key: key.to_owned(),
                value: value.to_owned(),
            })
        })
        .collect()
}
use crate::record::LedgerRecord;
use std::collections::BTreeMap;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};

/// Small process-local cache for immutable segment records.
#[derive(Debug, Default)]
pub(crate) struct IndexCache {
    entries: Mutex<BTreeMap<PathBuf, Arc<Vec<LedgerRecord>>>>,
}

impl IndexCache {
    /// Load one segment once and return the shared decoded record list.
    pub(crate) fn get_or_load<F>(
        &self,
        path: PathBuf,
        load: F,
    ) -> crate::error::Result<Arc<Vec<LedgerRecord>>>
    where
        F: FnOnce() -> crate::error::Result<Vec<LedgerRecord>>,
    {
        if let Some(records) = self.entries.lock().expect("cache mutex").get(&path).cloned() {
            return Ok(records);
        }
        let records = Arc::new(load()?);
        self.entries
            .lock()
            .expect("cache mutex")
            .insert(path, records.clone());
        Ok(records)
    }

    /// Remove a single immutable segment from the process-local cache.
    pub(crate) fn evict(&self, path: &std::path::Path) {
        self.entries.lock().expect("cache mutex").remove(path);
    }
}
