use std::sync::Arc;

/// Reads tab-delimited segment files through the shared immutable cache.
#[derive(Debug, Default)]
pub(crate) struct SegmentStore {
    cache: IndexCache,
}

impl SegmentStore {
    /// Decode a segment, reusing the cached representation when available.
    pub(crate) fn read_segment(&self, path: &Path) -> Result<Arc<Vec<LedgerRecord>>> {
        let owned_path: PathBuf = path.to_path_buf();
        self.cache.get_or_load(owned_path.clone(), || {
            let bytes = fs::read(&owned_path)
                .map_err(|_| LookupError::MissingSegment(owned_path.display().to_string()))?;
            decode_segment(&owned_path, &bytes)
        })
    }
}

fn decode_segment(path: &Path, bytes: &[u8]) -> Result<Vec<LedgerRecord>> {
    let text = std::str::from_utf8(bytes)
        .map_err(|_| LookupError::CorruptSegment(path.display().to_string()))?;
    text.lines()
        .map(|line| {
            let (key, value) = line
                .split_once('\t')
                .ok_or_else(|| LookupError::CorruptSegment(path.display().to_string()))?;
            Ok(LedgerRecord {
                key: key.to_owned(),
                value: value.to_owned(),
            })
        })
        .collect()
}
use crate::record::LedgerRecord;
use std::collections::BTreeMap;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};

/// Small process-local cache for immutable segment records.
#[derive(Debug, Default)]
pub(crate) struct IndexCache {
    entries: Mutex<BTreeMap<PathBuf, Arc<Vec<LedgerRecord>>>>,
}

impl IndexCache {
    /// Load one segment once and return the shared decoded record list.
    pub(crate) fn get_or_load<F>(
        &self,
        path: PathBuf,
        load: F,
    ) -> crate::error::Result<Arc<Vec<LedgerRecord>>>
    where
        F: FnOnce() -> crate::error::Result<Vec<LedgerRecord>>,
    {
        if let Some(records) = self.entries.lock().expect("cache mutex").get(&path).cloned() {
            return Ok(records);
        }
        let records = Arc::new(load()?);
        self.entries
            .lock()
            .expect("cache mutex")
            .insert(path, records.clone());
        Ok(records)
    }

    /// Remove a single immutable segment from the process-local cache.
    pub(crate) fn evict(&self, path: &std::path::Path) {
        self.entries.lock().expect("cache mutex").remove(path);
    }
}
